function drawPlayer(ctx) {
  const p = G.player;
  const sprites = G.offscreen.player;
  if (!sprites) return;
  ctx.save();
  ctx.translate(p.x, p.y);

  /* 无敌闪烁 */
  let alpha = 1;
  if (G.invincible > 0 && Math.floor(G.invincible / 4) % 2 === 0) {
    alpha = 0.35;
  }

  /* 阴影（滑铲时随旋转进度平滑过渡为宽扁椭圆） */
  const sliding = p.state === STATE_SLIDE;
  let shFrac = 0; // 0=正常阴影, 1=滑铲阴影
  if (sliding) {
    const progress = 1 - p.stateTimer / SLIDE_DURATION;
    shFrac = progress < 0.18 ? progress / 0.18
           : progress < 0.75 ? 1
           : Math.max(0, 1 - (progress - 0.75) / 0.25);
  }
  ctx.fillStyle = `rgba(0,0,0,${0.25 + shFrac * 0.10})`;
  ctx.beginPath();
  ctx.ellipse(
    -22 * shFrac,              // x 左移
    12 - 6 * shFrac,           // y 上移
    20 + 15 * shFrac,           // rx 拉宽
    7 - 2 * shFrac,            // ry 压扁
    0, 0, Math.PI * 2
  );
  ctx.fill();

  /* 选择精灵帧 */
  let frame = sprites.run[0]; // 默认第一帧
  const SW = 80, SH = 100;

  if (p.state === STATE_RUN) {
    /* 庆祝动画 */
    if (p.celebrateTimer > 0 && p.celebrateType) {
      if (p.celebrateType === 'lookback') {
        frame = sprites.lookback;
      } else if (p.celebrateType === 'kick') {
        frame = p.celebrateTimer > 15 ? sprites.kick : sprites.run[Math.floor(G.frameCount / 8) % 8];
      }
    } else {
      /* 8帧跑步循环 ~7.5fps */
      frame = sprites.run[Math.floor(G.frameCount / 8) % 8];
    }
  } else if (p.state === STATE_JUMP) {
    /* 4阶段跳跃动画：预蹲(0.25s)→腾空(1.0s)→下落(0.7s)→落地(0.55s) */
    const t = p.stateTimer;
    if (t > 135)        frame = sprites.jump[0];  // 预蹲蓄力
    else if (t > 75)    frame = sprites.jump[1];  // 腾空上升
    else if (t > 33)    frame = sprites.jump[2];  // 下落
    else                frame = sprites.jump[3];  // 落地缓冲
  } else if (p.state === STATE_SLIDE) {
    /* 6阶段滑铲：下蹲→前倾→俯冲→贴地1→贴地2→起身，旋转角平滑过渡 */
    const t = p.stateTimer;
    if (t > 85)         frame = sprites.slide[0]; // 下蹲
    else if (t > 68)    frame = sprites.slide[1]; // 前倾
    else if (t > 50)    frame = sprites.slide[2]; // 俯冲
    else if (t > 32)    frame = sprites.slide[3]; // 贴地1
    else if (t > 16)    frame = sprites.slide[4]; // 贴地2
    else                frame = sprites.slide[5]; // 起身
  } else if (p.state === STATE_HIT) {
    frame = sprites.hit;
  }

  /* 绘制精灵（居中，底部对齐到地面） */
  if (alpha < 1) ctx.globalAlpha = alpha;

  if (p.state === STATE_SLIDE) {
    /* 平滑旋转：progress 0→0.2 快速下潜, 0.2→0.75 保持-90°, 0.75→1 缓升恢复 */
    const progress = 1 - p.stateTimer / SLIDE_DURATION;
    let rot;
    if (progress < 0.18) {
      rot = -Math.PI / 2 * (1 - Math.pow(1 - progress / 0.18, 3)); // ease-out 下潜
    } else if (progress < 0.75) {
      rot = -Math.PI / 2; // 保持贴地
    } else {
      rot = -Math.PI / 2 * Math.pow(1 - (progress - 0.75) / 0.25, 3); // ease-in 起身
    }
    const frac = Math.abs(rot) / (Math.PI / 2); // 0=直立, 1=水平
    const sy = -92 + frac * 27;                  // 位置插值: -92(直立) → -65(水平)

    ctx.save();
    ctx.rotate(rot);
    ctx.drawImage(frame, -40, sy);
    if (frac > 0.4) {
      /* 高速运动线（仅大幅旋转时） */
      ctx.strokeStyle = 'rgba(255,255,255,0.18)';
      ctx.lineWidth = 1;
      for (let i = 0; i < 2; i++) {
        ctx.beginPath();
        ctx.moveTo(-5 + i * 15, sy + 20);
        ctx.lineTo(-5 + i * 15, sy + 35);
        ctx.stroke();
      }
    }

