function render() {
  const ctx = G.ctx;
  ctx.clearRect(0, 0, G.W, G.H);
  ctx.save();
  if (G.shakeDuration > 0) {
    ctx.translate(
      (Math.random() - 0.5) * G.shakeX * 2,
      (Math.random() - 0.5) * G.shakeY * 2
    );
  }
  renderBackground(ctx);
  renderEntities(ctx);
  renderParticles(ctx);
  renderPopups(ctx);
  ctx.restore();
  renderEffects(ctx);
  renderUI(ctx);
}

function renderBackground(ctx) {
  /* 天空 */
  ctx.drawImage(G.offscreen.sky, 0, 0);
  /* 云层（独立慢速视差） */
  const cloudOffset = (G.distance * PARALLAX_CLOUD) % G.offscreen.clouds.width;
  if (cloudOffset + G.W <= G.offscreen.clouds.width) {
    ctx.drawImage(G.offscreen.clouds, cloudOffset, 0, G.W, G.offscreen.clouds.height, 0, 0, G.W, G.offscreen.clouds.height);
  } else {
    const w1 = G.offscreen.clouds.width - cloudOffset;
    ctx.drawImage(G.offscreen.clouds, cloudOffset, 0, w1, G.offscreen.clouds.height, 0, 0, w1, G.offscreen.clouds.height);
    ctx.drawImage(G.offscreen.clouds, 0, 0, G.W - w1, G.offscreen.clouds.height, w1, 0, G.W - w1, G.offscreen.clouds.height);
  }
  /* 远山（最慢视差） */
  const mtnOffset = (G.distance * PARALLAX_MOUNTAIN) % G.offscreen.mountains.width;
  if (mtnOffset + G.W <= G.offscreen.mountains.width) {
    ctx.drawImage(G.offscreen.mountains, mtnOffset, 0, G.W, G.offscreen.mountains.height, 0, G.vanishY - G.offscreen.mountains.height + 60, G.W, G.offscreen.mountains.height);
  } else {
    const w1 = G.offscreen.mountains.width - mtnOffset;
    ctx.drawImage(G.offscreen.mountains, mtnOffset, 0, w1, G.offscreen.mountains.height, 0, G.vanishY - G.offscreen.mountains.height + 60, w1, G.offscreen.mountains.height);
    ctx.drawImage(G.offscreen.mountains, 0, 0, G.W - w1, G.offscreen.mountains.height, w1, G.vanishY - G.offscreen.mountains.height + 60, G.W - w1, G.offscreen.mountains.height);
  }
  /* 城市天际线（远景） */
  const cityOffset = (G.distance * PARALLAX_FAR) % (G.W * 3);
  if (cityOffset + G.W <= G.offscreen.city.width) {
    ctx.drawImage(G.offscreen.city, cityOffset, 0, G.W, G.H*0.25, 0, G.vanishY - 30, G.W, G.H*0.25);
  } else {
    const w1 = G.offscreen.city.width - cityOffset;
    ctx.drawImage(G.offscreen.city, cityOffset, 0, w1, G.H*0.25, 0, G.vanishY - 30, w1, G.H*0.25);
    ctx.drawImage(G.offscreen.city, 0, 0, G.W - w1, G.H*0.25, w1, G.vanishY - 30, G.W - w1, G.H*0.25);
  }
  /* 近景建筑 */
  const nearOffset = (G.distance * PARALLAX_NEAR) % (G.W * 2);
  if (nearOffset + G.W <= G.offscreen.nearCity.width) {
    ctx.drawImage(G.offscreen.nearCity, nearOffset, 0, G.W, G.H*0.35, 0, G.vanishY + 10, G.W, G.H*0.35);
  } else {
    const w1 = G.offscreen.nearCity.width - nearOffset;
    ctx.drawImage(G.offscreen.nearCity, nearOffset, 0, w1, G.H*0.35, 0, G.vanishY + 10, w1, G.H*0.35);
    ctx.drawImage(G.offscreen.nearCity, 0, 0, G.W - w1, G.H*0.35, w1, G.vanishY + 10, G.W - w1, G.H*0.35);
  }
  drawGround(ctx);
  drawTracks(ctx);
}

function renderEntities(ctx) {
  const entities = [];
  for (let i = 0; i < G.obstacles.length; i++) {
    const o = G.obstacles[i];
    if (!o.active) continue;
    entities.push({ type:'obstacle', obj:o, dist:o.dist, lane:o.lane });
  }
  for (let i = 0; i < G.trains.length; i++) {
    const t = G.trains[i];
    if (!t.active) continue;
    entities.push({ type:'train', obj:t, dist:t.dist, lane:t.lane });
  }
  for (let i = 0; i < G.coins.length; i++) {
    const c = G.coins[i];
    if (!c.active || c.collected) continue;
    entities.push({ type:'coin', obj:c, dist:c.dist, lane:c.lane });
  }
  for (let i = 0; i < G.powerups.length; i++) {
    const pu = G.powerups[i];
    if (!pu.active || pu.collected) continue;
    entities.push({ type:'powerup', obj:pu, dist:pu.dist, lane:pu.lane });
  }
  entities.sort((a, b) => b.dist - a.dist);
  const frontEntities = entities.filter(e => e.dist > 0);
  const behindEntities = entities.filter(e => e.dist <= 0);

  frontEntities.forEach(e => {
    const s = worldToScreen(e.dist);
    if (s.y < G.vanishY - 20 || s.y > G.H + 60) return;
    const sx = laneX(e.lane, e.dist);
    if (e.type === 'obstacle') drawObstacle(ctx, e.obj, sx, s.y, s.scale);
    else if (e.type === 'train') drawTrain(ctx, e.obj, e.lane, e.dist, sx, s.y, s.scale);
    else if (e.type === 'coin') drawCoin(ctx, e.obj, sx, s.y, s.scale);
    else if (e.type === 'powerup') drawPowerup(ctx, e.obj, sx, s.y, s.scale);
  });
  drawPlayer(ctx);
  behindEntities.forEach(e => {
    const s = worldToScreen(e.dist);
    if (s.y < G.vanishY - 20 || s.y > G.H + 60) return;
    const sx = laneX(e.lane, e.dist);
    if (e.type === 'obstacle') drawObstacle(ctx, e.obj, sx, s.y, s.scale);
    else if (e.type === 'train') drawTrain(ctx, e.obj, e.lane, e.dist, sx, s.y, s.scale);
    else if (e.type === 'coin') drawCoin(ctx, e.obj, sx, s.y, s.scale);
    else if (e.type === 'powerup') drawPowerup(ctx, e.obj, sx, s.y, s.scale);
  });
}

function renderParticles(ctx) {
  for (let i = 0; i < G.particles.length; i++) {
    const p = G.particles[i];
    if (!p.active) continue;
    const alpha = p.life / p.maxLife;
    ctx.globalAlpha = alpha;
    ctx.fillStyle = p.color;
    ctx.fillRect(p.x - p.size/2, p.y - p.size/2, p.size, p.size);
  }
  ctx.globalAlpha = 1;
}

