function drawGround(ctx) {
  const groundTop = G.vanishY + 30;
  const groundBot = G.H;

  /* 碎石地表渐变 */
  const grad = ctx.createLinearGradient(0, groundTop, 0, groundBot);
  grad.addColorStop(0, '#8b7355');
  grad.addColorStop(0.3, '#9b8b75');
  grad.addColorStop(0.7, '#a09080');
  grad.addColorStop(1, '#b0a090');
  ctx.fillStyle = grad;
  ctx.fillRect(0, groundTop, G.W, groundBot - groundTop);

  /* 轨道两侧路堤护坡 */
  drawEmbankments(ctx);

  /* 碎石纹理点 */
  ctx.fillStyle = 'rgba(120,110,100,0.3)';
  const seed = 42;
  for (let y = groundTop; y < groundBot; y += 12) {
    for (let x = 0; x < G.W; x += 14) {
      if (((x * 31 + y * 17 + seed) % 7) === 0) {
        ctx.fillRect(x, y, 2, 2);
      }
    }
  }

  /* 轨旁景物（电杆、灌木） */
  drawTracksideScenery(ctx);
}

/* 轨道两侧土堤/植被护坡 */
function drawEmbankments(ctx) {
  for (let lane = 0; lane < LANE_COUNT; lane++) {
    /* 每段距离画护坡梯形 */
    for (let d = 0; d < G.maxDist; d += 80) {
      const s0 = worldToScreen(d);
      const s1 = worldToScreen(d + 80);
      if (s0.y < G.vanishY || s1.y > G.H + 20) continue;

      const sc0 = Math.max(0.1, s0.scale);
      const sc1 = Math.max(0.1, s1.scale);

      const lx0 = laneX(lane, d);
      const lx1 = laneX(lane, d + 80);

      /* 左侧护坡 */
      const lOuter0 = lx0 - 22 * sc0, lOuter1 = lx1 - 22 * sc1;
      ctx.fillStyle = '#6b8e5a';
      ctx.beginPath();
      ctx.moveTo(lOuter0, s0.y);
      ctx.lineTo(lOuter1, s1.y);
      ctx.lineTo(lx1 - 12 * sc1, s1.y);
      ctx.lineTo(lx0 - 12 * sc0, s0.y);
      ctx.closePath();
      ctx.fill();
      /* 坡顶亮线 */
      ctx.strokeStyle = '#7a9e68';
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(lOuter0, s0.y);
      ctx.lineTo(lOuter1, s1.y);
      ctx.stroke();

      /* 右侧护坡 */
      const rOuter0 = lx0 + 22 * sc0, rOuter1 = lx1 + 22 * sc1;
      ctx.fillStyle = '#6b8e5a';
      ctx.beginPath();
      ctx.moveTo(lx0 + 12 * sc0, s0.y);
      ctx.lineTo(lx1 + 12 * sc1, s1.y);
      ctx.lineTo(rOuter1, s1.y);
      ctx.lineTo(rOuter0, s0.y);
      ctx.closePath();
      ctx.fill();
      ctx.strokeStyle = '#7a9e68';
      ctx.beginPath();
      ctx.moveTo(rOuter0, s0.y);
      ctx.lineTo(rOuter1, s1.y);
      ctx.stroke();
    }
  }
}

/* 轨旁景物 */
function drawTracksideScenery(ctx) {
  const poleInterval = 180; // 电杆间距（世界坐标）

  for (let lane = 0; lane < LANE_COUNT; lane++) {
    for (let d = poleInterval; d < G.maxDist; d += poleInterval) {
      const s = worldToScreen(d);
      if (s.y < G.vanishY + 10 || s.y > G.H + 40) continue;

      const lx = laneX(lane, d);
      const sc = Math.max(0.08, s.scale);
      const poleH = 35 * sc;
      const poleW = 3 * sc;

      /* 左侧电杆 */
      const lpx = lx - 28 * sc;
      ctx.fillStyle = '#5a4a3a';
      ctx.fillRect(lpx - poleW/2, s.y - poleH, poleW, poleH);
      /* 杆顶横梁 */
      ctx.fillRect(lpx - 6*sc, s.y - poleH, poleW * 4, poleW);
      /* 瓷瓶 */
      ctx.fillStyle = '#ddd';
      ctx.fillRect(lpx - 5*sc, s.y - poleH - 2*sc, 2*sc, 3*sc);
      ctx.fillRect(lpx + 2*sc, s.y - poleH - 2*sc, 2*sc, 3*sc);

      /* 右侧电杆 */
      const rpx = lx + 28 * sc;
      ctx.fillStyle = '#5a4a3a';
      ctx.fillRect(rpx - poleW/2, s.y - poleH, poleW, poleH);
      ctx.fillRect(rpx - 6*sc, s.y - poleH, poleW * 4, poleW);
      ctx.fillStyle = '#ddd';
      ctx.fillRect(rpx - 5*sc, s.y - poleH - 2*sc, 2*sc, 3*sc);
