function gameLoop(timestamp) {
  G.deltaTime = timestamp - G.lastTime;
  G.lastTime = timestamp;

  /* FPS 计算 */
  G.frameCount++;
  G.fpsFrameCount++;
  G.fpsTime += G.deltaTime;
  if (G.fpsTime >= 1000) {
    G.fps = G.fpsFrameCount;
    G.fpsFrameCount = 0;
    G.fpsTime = 0;
  }

  processInput();
  update();
  render();
  requestAnimationFrame(gameLoop);
}

/* =========================== 启动 =========================== */
init();
</script>
</body>
</html>

