}

function updateFinalize(p) {
  cleanupPool(G.obstacles, 30);
  cleanupPool(G.trains, 10);
  cleanupPool(G.coins, 40);
  cleanupPool(G.particles, 80);
  cleanupPool(G.powerups, 5);
  p.y = G.groundY;
  if (p.state === STATE_JUMP) {
    /* 跳跃弧线：先升后降，stateTimer 越小越接近落地 */
    const progress = 1 - p.stateTimer / JUMP_DURATION; // 0=起跳, 1=落地
    const arc = Math.sin(progress * Math.PI);          // 0→1→0 抛物线
    p.y = G.groundY - arc * JUMP_PEAK_HEIGHT;
  } else if (p.state === STATE_SLIDE) {
    /* 滑铲：旋转90°后角色水平贴地，脚部对齐地面 */
    p.y = G.groundY;
  }
  p.scale = 1.0;
  p.x = laneX(p.lane, 0);
  if (G.frameCount % DUST_INTERVAL === 0 && G.state === 'playing') {
    burstParticles(p.x, G.groundY + 12, 2, 20, 4, 0.8, [8, 18], ['rgba(180,160,140,0.5)']);
  }
}

/* =========================== 碰撞检测 =========================== */
function sameLane(obs) {
  return Math.abs(obs.lane - G.player.lane) < SAME_LANE_THRESHOLD;
}

