474	function preRenderAssets() {
475	  /* --- 天空渐变背景 --- */
476	  const skyCanvas = document.createElement('canvas');
477	  skyCanvas.width = G.W;
478	  skyCanvas.height = G.H;
479	  const skyCtx = skyCanvas.getContext('2d');
480	  const grad = skyCtx.createLinearGradient(0, 0, 0, G.vanishY + 40);
481	  grad.addColorStop(0, '#1a1a4e');
482	  grad.addColorStop(0.5, '#2d4a8e');
483	  grad.addColorStop(1, '#5ba3d9');
484	  skyCtx.fillStyle = grad;
485	  skyCtx.fillRect(0, 0, G.W, G.H);
486	  /* 云层 */
487	  skyCtx.fillStyle = 'rgba(255,255,255,0.08)';
488	  for (let ci = 0; ci < 8; ci++) {
489	    const cx = Math.random() * G.W;
490	    const cy = Math.random() * G.vanishY * 0.7;
491	    const cw = 60 + Math.random() * 120;
492	    skyCtx.beginPath();
493	    skyCtx.ellipse(cx, cy, cw, 12 + Math.random() * 10, 0, 0, Math.PI * 2);
494	    skyCtx.fill();
495	    skyCtx.beginPath();
496	    skyCtx.ellipse(cx + cw*0.3, cy - 8, cw*0.6, 10 + Math.random() * 8, 0, 0, Math.PI * 2);
497	    skyCtx.fill();
498	  }
499	  G.offscreen.sky = skyCanvas;
500	
501	  /* --- 远山剪影（最远视差层） --- */
502	  const mtnCanvas = document.createElement('canvas');
503	  mtnCanvas.width = G.W * 4;
504	  mtnCanvas.height = G.vanishY + 60;
505	  const mtnCtx = mtnCanvas.getContext('2d');
506	  /* 远山层次 */
507	  const mtnLayers = [
508	    { color: '#1a1a4e', yBase: 0.65, amp: 0.20, freq: 0.012 },
509	    { color: '#1e2058', yBase: 0.55, amp: 0.25, freq: 0.016 },
510	    { color: '#252868', yBase: 0.48, amp: 0.18, freq: 0.022 },
511	  ];
512	  mtnLayers.forEach(layer => {
513	    mtnCtx.fillStyle = layer.color;
514	    mtnCtx.beginPath();
515	    mtnCtx.moveTo(0, mtnCanvas.height);
516	    const baseY = mtnCanvas.height * layer.yBase;
517	    const amp = mtnCanvas.height * layer.amp;
518	    for (let x = 0; x <= mtnCanvas.width; x += 3) {
519	      const noise = Math.sin(x * layer.freq) * amp
520	                  + Math.sin(x * layer.freq * 2.3 + 1.5) * amp * 0.5
521	                  + Math.sin(x * layer.freq * 5.7 + 3.1) * amp * 0.25;
522	      mtnCtx.lineTo(x, baseY + noise);
523	    }
524	    mtnCtx.lineTo(mtnCanvas.width, mtnCanvas.height);
525	    mtnCtx.closePath();
526	    mtnCtx.fill();
527	  });
528	  /* 雪顶 */
529	  mtnCtx.fillStyle = 'rgba(220,230,255,0.25)';
530	  mtnCtx.beginPath();
531	  mtnCtx.moveTo(0, mtnCanvas.height);
532	  const snowY = mtnCanvas.height * 0.45;
533	  const snowAmp = mtnCanvas.height * 0.08;
534	  for (let x = 0; x <= mtnCanvas.width; x += 3) {
535	    const n = Math.sin(x * 0.022) * snowAmp + Math.sin(x * 0.048 + 2) * snowAmp * 0.6;
536	    const y = snowY + n;
537	    mtnCtx.lineTo(x, y);
538	  }
539	  mtnCtx.lineTo(mtnCanvas.width, mtnCanvas.height);
540	  mtnCtx.closePath();
541	  mtnCtx.fill();
542	  G.offscreen.mountains = mtnCanvas;
543	
544	  /* --- 云层（独立视差） --- */
545	  const cloudCanvas = document.createElement('canvas');
546	  cloudCanvas.width = G.W * 3;
547	  cloudCanvas.height = G.vanishY * 0.8;
548	  const cloudCtx = cloudCanvas.getContext('2d');
549	  for (let ci = 0; ci < 12; ci++) {
550	    const cx = Math.random() * cloudCanvas.width;
551	    const cy = Math.random() * cloudCanvas.height;
552	    const alpha = 0.04 + Math.random() * 0.08;
553	    cloudCtx.fillStyle = `rgba(255,255,255,${alpha})`;
554	    /* 多层椭圆云 */
555	    const baseW = 40 + Math.random() * 100;
556	    cloudCtx.beginPath();
557	    cloudCtx.ellipse(cx, cy, baseW, 8 + Math.random() * 12, 0, 0, Math.PI * 2);
558	    cloudCtx.fill();
559	    cloudCtx.beginPath();
560	    cloudCtx.ellipse(cx + baseW * 0.25, cy - 6, baseW * 0.55, 6 + Math.random() * 8, 0, 0, Math.PI * 2);
561	    cloudCtx.fill();
562	    cloudCtx.beginPath();
563	    cloudCtx.ellipse(cx - baseW * 0.2, cy - 3, baseW * 0.4, 5 + Math.random() * 6, 0, 0, Math.PI * 2);
564	    cloudCtx.fill();
565	  }
566	  G.offscreen.clouds = cloudCanvas;
567	
568	  /* --- 城市天际线（远景） --- */
569	  const cityCanvas = document.createElement('canvas');
570	  cityCanvas.width = G.W * 3; // 宽于屏幕用于视差滚动
571	  cityCanvas.height = G.H * 0.25;
572	  const cityCtx = cityCanvas.getContext('2d');
573	  /* 建筑剪影 */
574	  cityCtx.fillStyle = '#1a1a3e';
575	  const buildings = [];
576	  let bx = 0;
577	  while (bx < cityCanvas.width) {
578	    const bw = randInt(30, 100);
579	    const bh = randInt(40, cityCanvas.height * 0.85);
580	    buildings.push({ x: bx, w: bw, h: bh });
581	    bx += bw + randInt(5, 20);
582	  }
583	  buildings.forEach(b => {
584	    cityCtx.fillRect(b.x, cityCanvas.height - b.h, b.w, b.h);
585	    /* 远处涂鸦（简化色块） */
586	    if (Math.random() < 0.2 && b.w > 50) {
587	      const tagColors = ['#ff3366','#ff6600','#33ff66','#33ccff','#ff33cc'];
588	      cityCtx.fillStyle = tagColors[Math.floor(Math.random() * tagColors.length)];
589	      cityCtx.fillRect(b.x + 8, cityCanvas.height - b.h + 10, b.w - 16, 8);
590	    }
591	    /* 窗户光点 */
592	    cityCtx.fillStyle = 'rgba(255,220,150,0.3)';
593	    for (let wy = cityCanvas.height - b.h + 8; wy < cityCanvas.height - 8; wy += 12) {
594	      for (let wx = b.x + 6; wx < b.x + b.w - 6; wx += 10) {
595	        if (Math.random() < 0.4) cityCtx.fillRect(wx, wy, 3, 3);
596	      }
597	    }
598	    cityCtx.fillStyle = '#1a1a3e';
599	  });
600	  G.offscreen.city = cityCanvas;
601	
602	  /* --- 近景建筑（更大、暖色调） --- */
603	  const nearCanvas = document.createElement('canvas');
604	  nearCanvas.width = G.W * 2;
605	  nearCanvas.height = G.H * 0.35;
606	  const nearCtx = nearCanvas.getContext('2d');
607	  nearCtx.fillStyle = '#2a1a0a';
608	  let nx = 0;
609	  while (nx < nearCanvas.width) {
610	    const nw = randInt(60, 160);
611	    const nh = randInt(80, nearCanvas.height * 0.9);
612	    nearCtx.fillRect(nx, nearCanvas.height - nh, nw, nh);
613	    /* 更大更亮的窗户 */
614	    nearCtx.fillStyle = 'rgba(255,200,100,0.2)';
615	    for (let wy = nearCanvas.height - nh + 12; wy < nearCanvas.height - 10; wy += 16) {
616	      for (let wx = nx + 10; wx < nx + nw - 10; wx += 14) {
617	        if (Math.random() < 0.35) nearCtx.fillRect(wx, wy, 5, 6);
618	      }
619	    }
620	    /* 随机涂鸦标签（30%几率） */
621	    if (Math.random() < 0.3) {
622	      const tagW = randInt(30, nw - 10);
623	      const tagH = randInt(20, Math.min(60, nh - 20));
624	      const tagX = nx + randInt(5, nw - tagW - 5);
625	      const tagY = nearCanvas.height - nh + randInt(10, nh - tagH - 10);
626	      drawGraffitiTag(nearCtx, tagX, tagY, tagW, tagH);
627	    }
628	    nearCtx.fillStyle = '#2a1a0a';
629	    nx += nw + randInt(8, 30);
630	  }
631	  G.offscreen.nearCity = nearCanvas;
632	
633	  /* --- 玩家角色精灵表 --- */
634	  preRenderPlayerSprites();
