667	/* 涂鸦标签 -- 在指定位置绘制随机涂鸦 */
668	function drawGraffitiTag(ctx, x, y, w, h) {
669	  const colors = ['#ff3366','#ff6600','#ffcc00','#33ff66','#33ccff','#ff33cc','#aaff00','#ff0066'];
670	  const bgColors = ['#1a1a2e','#2a1a4e','#1a3a2e','#3a1a2e','#2a2a4e'];
671	
672	  /* 背景色块（涂鸦底板） */
